0. Set Up & Environment Verification

suppressPackageStartupMessages({
  library(tuber)
  library(httr2)
  library(tidyverse)
  library(quanteda)
  library(quanteda.textstats)
  library(quanteda.textplots)
  library(jsonlite)
  library(knitr)
})

# 0b. Verify required package versions: tuber &gt;= 2.0.0.9000 and httr2 &gt;= 1.1.0
tibble(
  package = c("tuber", "httr2"),
  installed_version = c(
    as.character(packageVersion("tuber")),
    as.character(packageVersion("httr2"))
  ),
  requirement_met = c(
    packageVersion("tuber") &gt;= "2.0.0.9000",
    packageVersion("httr2") &gt;= "1.1.0"
  )
) |&gt; kable(caption = "Package Version Verification (Part 0b)")


